static int next_codepoint(const unsigned char *s, int *i) {
    unsigned char c = s[(*i)++];

    if (c < 0x80)
        return c;

    if ((c & 0xE0) == 0xC0) {
        int cp = (c & 0x1F) << 6;
        cp |= s[(*i)++] & 0x3F;
        return cp;
    }

    if ((c & 0xF0) == 0xE0) {
        int cp = (c & 0x0F) << 12;
        cp |= (s[(*i)++] & 0x3F) << 6;
        cp |= s[(*i)++] & 0x3F;
        return cp;
    }

    int cp = (c & 0x07) << 18;
    cp |= (s[(*i)++] & 0x3F) << 12;
    cp |= (s[(*i)++] & 0x3F) << 6;
    cp |= s[(*i)++] & 0x3F;
    return cp;
}

static int normalize(int cp) {
    if (cp >= 'a' && cp <= 'z')
        return cp - 'a';

    if (cp >= 0x00E0 && cp <= 0x00E5) return 'a' - 'a';
    if (cp == 0x00E7) return 'c' - 'a';
    if (cp >= 0x00E8 && cp <= 0x00EB) return 'e' - 'a';
